STORY = [('yejin', '전세 만기가 2월 말.', 'My jeonse lease expires at the end of February.', [(51, '전세 만기가 2월 말')], ''), ('yejin', '그리고 내 동탄 새 아파트 입주가 6월 말.', 'And I move into my new apartment in Dongtan at the end of the sixth month.', [(52, '그리고 내 동탄 새 아파트 입주가 6월 말')], ''), ('yejin', '이렇게 딱 넉 달이 비는데,', 'So there is exactly a four-month gap,', [(53, '이렇게 딱 넉 달이')], 'The STT incorrectly transcribed 비는데 as 빚는데, so it is excluded from the alignment.'), ('yejin', '그 넉 달만 그냥 연장해 주면 얼마나 좋냐고.', 'how great would it be if they just extended it for those four months?', [(54, '그 넉 달만 그냥 연장해 주면 얼마나 좋냐고')], ''), ('yejin', '근데 그 집주인이 안 된다는 거야.', 'But the landlord says no.', [(55, '근데 그 집주인이 안 된다는 거야')], ''), ('yejin', '그냥 전세 연장을 하든 아니면 이사를 나가든지 하래요.', 'He told me to either extend the lease or move out.', [(56, '그냥 전세 연장을 하든 아니면 이사를 나가든지 하래요')], ''), ('yejin', '나 지금 길바닥에 나올 게 생겼다니까.', 'I am about to end up on the streets right now.', [(57, '나 지금 길바닥에 나올 게 생겼다니까')], ''), ('joonmo', '전세 연장해.', 'Extend the lease.', [(58, '전세 연장해')], ''), ('yejin', '2억을 더 달라는데?', 'They are asking for two hundred million won more?', [(59, '2억을 더 달라는데?')], ''), ('joonmo', '2억?', 'Two hundred million?', [(60, '2억?')], ''), ('joonmo', '월세 같은 거 없나? 단기 월세.', "Isn't there something like monthly rent? Short-term monthly rent.", [(64, '월세 같은 거 없나? 단기 월세')], ''), ('yejin', '넉 달 때우려고?', 'To fill in four months?', [(65, '넉 달 때우려고?')], ''), ('yejin', '이사 비용에 복비 더블로 내야 되지.', 'I would have to pay moving costs and realtor fees double.', [(66, '이사 비용에 복비 더블로 내야 되지')], '')]

